using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using TasiaCraft;
public static class OffCanvasTest {
 static string root,log;static int passed,edits,width;static LivePreview live;static Project project;
 static void Require(bool ok,string message){if(!ok)throw new Exception(message);File.AppendAllText(log,"PASS "+message+Environment.NewLine);passed++;}
 static byte[] Pixels(bool stage){live.UpdateLayout();int w=stage?project.Width:(int)Math.Ceiling(live.ActualWidth),h=stage?project.Height:(int)Math.Ceiling(live.ActualHeight);width=w;var b=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);b.Render(stage?(Visual)live.Stage:live);var pixels=new byte[w*h*4];b.CopyPixels(pixels,w*4,0);return pixels;}
 static int At(double x,double y){Point p=live.Stage.TransformToAncestor(live).Transform(new Point(x,y));int px=(int)Math.Round(p.X),py=(int)Math.Round(p.Y);if(px<0||px>=width||py<0||py>=(int)Math.Ceiling(live.ActualHeight))throw new Exception("Sample outside preview: "+p);return(py*width+px)*4;}
 static bool Bright(byte[] p,int n){return p[n+2]>235&&p[n+1]<20&&p[n]<20;}
 static bool Dim(byte[] p,int n){return p[n+2]>=70&&p[n+2]<=105&&p[n+1]>=15&&p[n+1]<=45&&p[n]>=15&&p[n]<=50;}
 static void Edges(string label){var p=Pixels(false);Require(Bright(p,At(project.Width/2.0,project.Height/2.0)),label+" project interior remains bright red");Require(Dim(p,At(-5,project.Height/2.0)),label+" left overflow remains visible beneath shade");Require(Dim(p,At(project.Width+5,project.Height/2.0)),label+" right overflow remains visible beneath shade");Require(Dim(p,At(project.Width/2.0,-5)),label+" top overflow remains visible beneath shade");Require(Dim(p,At(project.Width/2.0,project.Height+5)),label+" bottom overflow remains visible beneath shade");}
 [STAThread]public static void Main(string[] args){root=args[0];Directory.CreateDirectory(root);log=Path.Combine(root,"results.txt");File.WriteAllText(log,"");var app=new Application();live=new LivePreview{Background=new SolidColorBrush(Color.FromRgb(28,35,39))};var window=new Window{Title="TatsiaCraft isolated off-canvas acceptance",Width=700,Height=460,Content=live};window.Loaded+=async(s,e)=>{try{
  string source=Path.Combine(root,"red.png");using(var b=new System.Drawing.Bitmap(160,80)){using(var g=System.Drawing.Graphics.FromImage(b))g.Clear(System.Drawing.Color.Red);b.Save(source,System.Drawing.Imaging.ImageFormat.Png);}var m=new Media{Path=source,Name="red.png",Kind="image",Width=160,Height=80,Duration=5};project=new Project{Width=80,Height=40};project.Media.Add(m);var clip=new Clip{MediaId=m.Id,Duration=1,NativeSize=true};project.Clips.Add(clip);live.BeforeEdit+=()=>edits++;live.SetProject(project);live.Seek(.2);live.SetViewZoom(2);await Task.Delay(120);string original=new JavaScriptSerializer().Serialize(project);
  var shade=live.Stage.Children.OfType<OffCanvasShade>().Single();Require(!shade.IsHitTestVisible,"workspace shade does not intercept pointer input");Require(Panel.GetZIndex(shade)==int.MaxValue-1,"shade sits above source layers and below selection handles");Edges("initial");var pixels=Pixels(false);int outside=At(-70,20);Require(Math.Abs(pixels[outside+2]-28)<3&&Math.Abs(pixels[outside+1]-35)<3&&Math.Abs(pixels[outside]-39)<3,"empty workspace retains original background color");
  var withShade=Pixels(true);shade.Visibility=Visibility.Collapsed;var withoutShade=Pixels(true);Require(withShade.SequenceEqual(withoutShade),"project-sized Stage bitmap is identical with shade hidden or visible");shade.Visibility=Visibility.Visible;Require(Bright(withShade,(20*80+40)*4),"project-sized bitmap contains undimmed source pixels");
  live.SetSelection(clip);await Task.Delay(60);var handles=live.Stage.Children.OfType<Canvas>().First();Require(handles.Children.Count>0&&Panel.GetZIndex(handles)>Panel.GetZIndex(shade),"selection grips remain above workspace shade");pixels=Pixels(false);int edge=At(-40,20);Require(pixels[edge]>100&&pixels[edge+1]>100,"off-canvas selection outline remains bright above shade");live.SetSelection(null);
  live.SetViewOffset(50,30);await Task.Delay(80);Edges("panned");live.SetViewZoom(3);await Task.Delay(80);Edges("zoomed");Require(new JavaScriptSerializer().Serialize(project)==original&&edits==0,"viewport shading pan and zoom preserve project serialization and edit history");
  clip.Scale=1.5;clip.Rotation=45;live.Refresh();await Task.Delay(80);Edges("rotated scaled");clip.Scale=1;clip.Rotation=0;project.Width=100;project.Height=50;live.SetProject(project);await Task.Delay(80);Edges("resized project");
  project.Width=80;project.Height=40;live.SetProject(project);await Task.Delay(60);string output=Path.Combine(root,"export.mp4"),png=Path.Combine(root,"export.png");Engine.Render(project,output,null);Engine.Run("ffmpeg","-y -v error -ss 0.2 -i "+Engine.Quote(output)+" -frames:v 1 -threads 1 "+Engine.Quote(png));using(var b=new System.Drawing.Bitmap(png)){Require(b.Width==80&&b.Height==40,"export retains project frame dimensions");foreach(var point in new[]{new System.Drawing.Point(2,2),new System.Drawing.Point(40,20),new System.Drawing.Point(77,37)}){var c=b.GetPixel(point.X,point.Y);Require(c.R>230&&c.G<25&&c.B<25,"decoded export pixel remains bright at "+point);}}
  var next=new Project{Width=80,Height=40};next.Media.Add(m);next.Clips.Add(new Clip{MediaId=m.Id,Duration=1,NativeSize=true});project=next;live.SetProject(next);live.Seek(.2);await Task.Delay(80);Edges("new project");Require(live.Stage.Children.OfType<OffCanvasShade>().Count()==1,"switching projects retains exactly one shade");Require(edits==0,"shade lifecycle creates no document edit checkpoint");live.Dispose();File.AppendAllText(log,"PASS total "+passed+Environment.NewLine);app.Shutdown(0);
 }catch(Exception ex){File.AppendAllText(log,"FAIL "+ex+Environment.NewLine);live.Dispose();app.Shutdown(1);}};app.Run(window);}
}
